module asyn_fifo (
    input wclk, 
    input rclk, 
    input wrstn, 
    input rrstn, 
    input winc, 
    input rinc, 
    input [WIDTH-1:0] wdata,
    output wfull, 
    output rempty, 
    output [WIDTH-1:0] rdata
);
// Parameter definitions
parameter WIDTH = 8;
parameter DEPTH = 16;
// Internal signals
reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];
reg [WIDTH-1:0] rdata_reg;
reg [DEPTH-1:0] wen, ren;
reg [DEPTH-1:0] waddr, raddr;
reg [DEPTH-1:0] waddr_bin, raddr_bin;
reg [3:0] wptr, rptr;
reg [3:0] wptr_buff, rptr_buff;
reg [3:0] wptr_syn, rptr_syn;
reg wfull_reg, rempty_reg;
// Write enable and read enable logic
assign wen = winc & !wfull;
assign ren = rinc & !rempty;
// Write address logic
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr <= 0;
    end else if (winc && !wfull) begin
        waddr <= waddr + 1;
    end
end
// Read address logic
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr <= 0;
    end else if (rinc && !rempty) begin
        raddr <= raddr + 1;
    end
end
// Write pointer logic
always @(*) begin
    wptr[3] = waddr_bin[3];
    wptr[2] = waddr_bin[3] ^ waddr_bin[2];
    wptr[1] = waddr_bin[2] ^ waddr_bin[1];
    wptr[0] = waddr_bin[1] ^ waddr_bin[0];
end
// Read pointer logic
always @(*) begin
    rptr[3] = raddr_bin[3];
    rptr[2] = raddr_bin[3] ^ raddr_bin[2];
    rptr[1] = raddr_bin[2] ^ raddr_bin[1];
    rptr[0] = raddr_bin[1] ^ raddr_bin[0];
end
// Write pointer buffer logic
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end
// Read pointer buffer logic
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end
// Synchronize write pointer logic
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_syn <= 0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end
// Synchronize read pointer logic
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_syn <= 0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end
// Generate full and empty signals
always @(*) begin
    wfull_reg = (wptr == {~rptr_syn[3], rptr_syn[2:0]});
    rempty_reg = (rptr == wptr_syn);
end
// Assign outputs
assign wfull = wfull_reg;
assign rempty = rempty_reg;
assign rdata = rdata_reg;
// Connect input/output signals to RAM instance
always @(posedge wclk) begin
    if (wen) begin
        RAM_MEM[waddr] <= wdata;
    end
end
always @(posedge rclk) begin
    if (ren) begin
        rdata_reg <= RAM_MEM[raddr];
    end
end
endmodule
